 693| 						error.message = `${String(error.data.message)} (${error.response.status})`;
 694| 					}
 695| 				}
 696| 
 697| 				// `request` and `options` are always available
 698| 				console.log(`Request to ${request.url} failed`, options.context);
 699| 
 700| 				return error;
 701| 			}
 702| 		]
 703| 	}
 704| });
 705| ```
