 903| ```js
 904| import ky from 'ky';
 905| import {DateTime} from 'luxon';
 906| 
 907| const json = await ky('https://example.com', {
 908| 	stringifyJson: data => JSON.stringify(data, (key, value) => {
 909| 		if (key.endsWith('_at')) {
 910| 			return DateTime.fromISO(value).toSeconds();
 911| 		}
 912| 
 913| 		return value;
 914| 	})
 915| }).json();
 916| ```
