1134| 		beforeRetry: [
1135| 			async ({request, options, error, retryCount}) => {
1136| 				const shouldStopRetry = await ky('https://example.com/api');
1137| 				if (shouldStopRetry) {
1138| 					return ky.stop;
1139| 				}
1140| 			}
1141| 		]
1142| 	}
1143| });
