1420| ```js
1421| import ky, {isNetworkError} from 'ky';
1422| 
1423| try {
1424| 	await ky('https://example.com').json();
1425| } catch (error) {
1426| 	if (isNetworkError(error)) {
1427| 		console.log('Network error:', error.message);
1428| 		console.log('Original error:', error.cause);
1429| 	}
1430| }
