  9| type ReplaceMarked<T> = {
 10| 	[replaceSymbol]: true;
 11| 	value: T;
 12| 	toJSON: () => T;
 13| };
 14| 
 15| type ReplaceState<T> = {
 16| 	isReplace: boolean;
 17| 	value: T;
 18| };
