 20| const getReplaceState = <T>(value: T): ReplaceState<T> =>
 21| 	isObject(value) && (value as any)[replaceSymbol] === true
 22| 		? {
 23| 			isReplace: true,
 24| 			value: (value as unknown as ReplaceMarked<T>).value,
 25| 		}
 26| 		: {
 27| 			isReplace: false,
 28| 			value,
 29| 		};
