 31| /**
 32| Wraps a value so that `ky.extend()` will replace the parent value instead of merging with it. Works with hooks, headers, search parameters, context, and any other deep-merged option.
 33| 
 34| Inside the `json` option, which holds your own data, use it only where it replaces an inherited value. Ky does not look for it anywhere else there. The `context` option is merged shallowly, so only a wrapper around the whole `context` is supported.
 35| 
 36| By default, `.extend()` deep-merges options with the parent instance: hooks get appended, headers get merged, and search parameters get accumulated. Use `replaceOption` when you want to fully replace a merged property instead.
 37| 
 38| @example
 39| ```
 40| import ky, {replaceOption} from 'ky';
 41| 
 42| const base = ky.create({
 43| 	hooks: {beforeRequest: [addAuth, addTracking]},
 44| });
 45| 
 46| // Replaces instead of appending
 47| const extended = base.extend({
 48| 	hooks: replaceOption({beforeRequest: [onlyThis]}),
 49| });
 50| // hooks.beforeRequest is now [onlyThis], not [addAuth, addTracking, onlyThis]
 51| ```
 52| */
 53| export const replaceOption = <T>(value: T): T => {
 54| 	const markedValue: ReplaceMarked<T> = {
 55| 		[replaceSymbol]: true,
 56| 		value,
 57| 		// The leftover pass below skips `json`, so a wrapper there with nothing to replace is unwrapped when the body is serialized.
 58| 		toJSON: () => value,
 59| 	};
 60| 	return markedValue as unknown as T;
 61| };
