20| 	try {
21| 		return await new Promise((resolve, reject) => {
22| 			timeoutId = setTimeout(() => {
23| 				timedOut = true;
24| 
25| 				abortController?.abort();
26| 
27| 				reject(new TimeoutError(request));
28| 			}, options.timeout);
29| 
30| 			// Called unbound so a native `window.fetch` is not invoked with `options` as `this`, which throws "Illegal invocation" in browsers.
31| 			// A synchronous throw rejects the promise, and `finally` still clears the timer so it cannot abort a later retry attempt.
32| 			const {fetch} = options;
